const AdmZip = require('adm-zip');
const PDFDocument = require('pdfkit');
const fs = require('fs');

// Read docx content
const zip = new AdmZip('testbed/docs/travel_summary.docx');
const xml = zip.readAsText('word/document.xml');

// Parse paragraphs with their styles
const paragraphs = [];
const pRegex = /<w:p[ >](.*?)<\/w:p>/gs;
let match;
while ((match = pRegex.exec(xml)) !== null) {
  const pContent = match[1];
  // Determine style
  let style = 'normal';
  const styleMatch = pContent.match(/<w:pStyle w:val=\"([^\"]+)\"/);
  if (styleMatch) {
    style = styleMatch[1];
  }
  // Extract text runs
  const textParts = [];
  const runRegex = /<w:t[^>]*>(.*?)<\/w:t>/gs;
  let tm;
  while ((tm = runRegex.exec(pContent)) !== null) {
    textParts.push(tm[1]);
  }
  const text = textParts.join('');
  if (text) {
    paragraphs.push({ style, text });
  }
}

// Create PDF
const doc = new PDFDocument({
  size: 'LETTER',
  margins: { top: 72, bottom: 72, left: 72, right: 72 }
});
const output = fs.createWriteStream('testbed/docs/travel_summary.pdf');
doc.pipe(output);

for (const p of paragraphs) {
  if (p.style === 'Title') {
    doc.fontSize(22).font('Helvetica-Bold').text(p.text, { align: 'center' });
    doc.moveDown(0.8);
  } else if (p.style === 'Heading1') {
    doc.moveDown(0.5);
    doc.fontSize(16).font('Helvetica-Bold').text(p.text);
    doc.moveDown(0.3);
    // Draw a line under the heading
    const y = doc.y;
    doc.moveTo(72, y).lineTo(540, y).strokeColor('#cccccc').lineWidth(1).stroke();
    doc.moveDown(0.3);
  } else {
    // Check if it's the Maya Chen note (italic style)
    if (p.text.includes('Seattle travel records are complete')) {
      doc.moveDown(0.3);
      doc.fontSize(10).font('Helvetica-Oblique').text(p.text, { align: 'left' });
      doc.moveDown(0.3);
    } else {
      doc.fontSize(10).font('Helvetica').text(p.text);
      doc.moveDown(0.15);
    }
  }
}

doc.end();
output.on('finish', () => {
  console.log('PDF created successfully: testbed/docs/travel_summary.pdf');
  const stats = fs.statSync('testbed/docs/travel_summary.pdf');
  console.log('File size: ' + (stats.size / 1024).toFixed(1) + ' KB');
});
"

