const fs = require('fs');
const zlib = require('zlib');
const buf = fs.readFileSync('testbed/docs/travel_summary.pdf');
const text = buf.toString('binary');

const streamRegex = /stream\r?\n([\s\S]*?)endstream/g;
let m;
const allText = [];
while ((m = streamRegex.exec(text)) !== null) {
  try {
    const raw = Buffer.from(m[1], 'binary');
    const decompressed = zlib.inflateSync(raw).toString();
    // Extract hex strings from PDF operators
    const hexRegex = /<([0-9a-f]+)>/gi;
    let hm;
    while ((hm = hexRegex.exec(decompressed)) !== null) {
      const decoded = Buffer.from(hm[1], 'hex').toString();
      if (decoded.length > 2) allText.push(decoded);
    }
  } catch(e) {}
}
const fullText = allText.join('');
const checks = [
  'Travel Booking Summary', 'Flights', 'Hotels', 'Car Rentals',
  'C4C633', 'HR-7D93', 'CR-BE00',
  'Seattle travel records are complete and up to date'
];
for (const c of checks) {
  console.log((fullText.includes(c) ? '✅' : '❌') + ' ' + c);
}
