const fs = require('fs');
const zlib = require('zlib');
const buf = fs.readFileSync('testbed/docs/travel_summary.pdf');
const text = buf.toString('binary');

const streamRegex = /stream\r?\n([\s\S]*?)endstream/g;
let m;
while ((m = streamRegex.exec(text)) !== null) {
  try {
    const raw = Buffer.from(m[1], 'binary');
    const decompressed = zlib.inflateSync(raw).toString();
    // Extract full TJ arrays - combine all hex parts
    const tjRegex = /\[(.*?)\]\s*TJ/gs;
    let tj;
    while ((tj = tjRegex.exec(decompressed)) !== null) {
      const hexParts = [];
      const hRegex = /<([0-9a-f]+)>/gi;
      let h;
      while ((h = hRegex.exec(tj[1])) !== null) {
        hexParts.push(h[1]);
      }
      const line = Buffer.from(hexParts.join(''), 'hex').toString();
      if (line.includes('Seattle travel records') || line.includes('Travel Booking')) {
        console.log('FOUND:', line);
      }
    }
  } catch(e) {}
}
